function make(t,u,row,kind){const [key,p,r]=row;const [prompt,...rest]=kind==='PRIMARY'?p:r;const rationale=rest.pop();const tests=`${t}U${u}`;return Object.freeze({id:`REF-${tests}-${kind==='PRIMARY'?'Q':'QR'}`,kind,tests,unit:tests,topic:t,module:`module-${t.slice(1)}`,screen:`${tests.toLowerCase()}-s1`,prompt,choices:Object.freeze(rest),correctChoice:0,rationale,...assessmentSource(tests,prompt,S[key]),...(kind==='REPLACEMENT'?{replaces:`REF-${tests}-Q`}:{})});}
export const TOPIC_QUIZZES=Object.freeze(Object.fromEntries(TOPICS.map(t=>[t.code,Object.freeze(DATA[t.code].map((r,i)=>make(t.code,i+1,r,'PRIMARY')))])));
export const REPLACEMENTS=Object.freeze(Object.fromEntries(TOPICS.map(t=>[t.code,Object.freeze(DATA[t.code].map((r,i)=>make(t.code,i+1,r,'REPLACEMENT')))])));
export const SOURCE_REFERENCES=Object.freeze(S);
for(const t of TOPICS){if(DATA[t.code].length!==t.units.length||TOPIC_QUIZZES[t.code].length<3)throw Error(`REF quiz coverage ${t.code}`);for(const q of [...TOPIC_QUIZZES[t.code],...REPLACEMENTS[t.code]])if(q.choices.length!==4||new Set(q.choices).size!==4||!q.rationale||q.correctChoice!==0)throw Error(`REF quiz schema ${q.id}`);}
export function getFormativeInventory(){return {TOPIC_QUIZZES,REPLACEMENTS};}
